def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    my_d = my.count('D')
    op_d = op.count('D')

    if op_d == n:
        return 'D'

    if op_d == 0:
        if n < 10:
            return 'C'
        if n == 10:
            return 'D'
        if n == 11:
            return 'C'
        if n == 12:
            return 'C'
        return 'D'

    if n >= 99:
        return 'D'

    if my_d > op_d:
        return 'C'
    if op_d > my_d:
        return 'D'
    return 'C'
